/**
 * AC14: the Node SDK's response parsing agrees with the shared cross-language fixture.
 *
 * Loads sdks/testdata/scan-fixture.json (generated by sdks/testdata/generate_fixture.py,
 * which imports and runs the real piishield.detectors.recognizers.scan_text, not
 * hand-guessed values) and asserts that ScanResult.fromApi, given the fixture's
 * expected_api_response (shaped like the real detectors.schemas.ScanResultOut, which is
 * what scan() now calls), finds the same categories at the same spans as the Python
 * SDK's own test (sdks/python/tests/unit/test_fixture_parity.py) asserts against. This
 * is the "byte-identical... asserted in both languages" proof AC14 asks for. Every value
 * is exact (no confidence range to tolerate), since the fixture is generated from the
 * real detector, not guessed.
 */

import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { describe, expect, it } from "vitest";

import { ScanResult } from "../../src/index.js";

const here = dirname(fileURLToPath(import.meta.url));
const fixturePath = join(here, "..", "..", "..", "testdata", "scan-fixture.json");

interface ExpectedFinding {
  category: string;
  start: number;
  end: number;
  value_for_fixture_only: string;
  confidence: number;
  checksum_valid: boolean | null;
  recognizer: string;
}

interface Fixture {
  sample_text: string;
  findings: ExpectedFinding[];
  expected_api_response: { findings: Record<string, unknown>[] };
}

function loadFixture(): Fixture {
  return JSON.parse(readFileSync(fixturePath, "utf8")) as Fixture;
}

describe("shared scan fixture", () => {
  it("exists on disk", () => {
    expect(() => loadFixture()).not.toThrow();
  });

  it("ScanResult.fromApi matches the fixture's categories and spans", () => {
    const fixture = loadFixture();
    const result = ScanResult.fromApi(fixture.expected_api_response);
    expect(result.findings).toHaveLength(fixture.findings.length);
    result.findings.forEach((parsed, i) => {
      const expected = fixture.findings[i]!;
      expect(parsed.category).toBe(expected.category);
      expect(parsed.start).toBe(expected.start);
      expect(parsed.end).toBe(expected.end);
      expect(parsed.confidence).toBe(expected.confidence);
      expect(parsed.checksumValid).toBe(expected.checksum_valid);
      expect(parsed.recognizer).toBe(expected.recognizer);
    });
  });

  it("every finding's span, sliced from sample_text, matches value_for_fixture_only", () => {
    const fixture = loadFixture();
    for (const f of fixture.findings) {
      expect(fixture.sample_text.slice(f.start, f.end)).toBe(f.value_for_fixture_only);
    }
  });
});
